// Corrections and the request path (spec 0003 T11, R15, R15a, R16,
// R16a), plus T13's chat-side conveniences: confirming, undoing,
// remembering, repeating a capture and listing recent ones. Amount
// and merchant are financial facts (own+unconfirmed for a member,
// unconditional for hh_admin -- posting_member_update_guard and
// transaction_member_update_guard already enforce this, ADR 0042's
// acts_as); category and project are never financial facts (R15a) so
// any member changes them unconditionally; only hh_admin deletes. A
// write this workflow attempts and the database refuses is never
// retried as something else -- for amount/merchant it becomes a
// correction_request instead, notifying the admins for real.
const crypto = require('crypto');
const http = require('http');
const https = require('https');
const { URL } = require('url');

const PG = 'http://postgrest:3000';

function b64url(buf) {
  return buf.toString('base64').replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
}

function mintToken(role, memberId) {
  const header = b64url(Buffer.from(JSON.stringify({ alg: 'HS256', typ: 'JWT' })));
  const payload = b64url(Buffer.from(JSON.stringify({ role, member_id: memberId, exp: Math.floor(Date.now() / 1000) + 60 })));
  const signingInput = `${header}.${payload}`;
  const signature = b64url(crypto.createHmac('sha256', $env.PGRST_JWT_SECRET).update(signingInput).digest());
  return `${signingInput}.${signature}`;
}

function httpJson(method, url, headers, body) {
  return new Promise((resolve, reject) => {
    const bodyStr = body !== undefined ? JSON.stringify(body) : undefined;
    const u = new URL(url);
    const options = {
      hostname: u.hostname, port: u.port, path: u.pathname + u.search, method,
      headers: Object.assign({ 'Content-Type': 'application/json' }, headers, bodyStr ? { 'Content-Length': Buffer.byteLength(bodyStr) } : {}),
    };
    const req = http.request(options, (res) => {
      let data = '';
      res.on('data', (c) => (data += c));
      res.on('end', () => {
        let parsed = null;
        try { parsed = data ? JSON.parse(data) : null; } catch (e) { parsed = data; }
        resolve({ status: res.statusCode, body: parsed });
      });
    });
    req.on('error', reject);
    if (bodyStr) req.write(bodyStr);
    req.end();
  });
}

function telegramSend(botToken, chatId, text) {
  return new Promise((resolve) => {
    const bodyStr = JSON.stringify({ chat_id: chatId, text });
    const req = https.request({
      hostname: 'api.telegram.org', path: `/bot${botToken}/sendMessage`, method: 'POST',
      headers: { 'Content-Type': 'application/json', 'Content-Length': Buffer.byteLength(bodyStr) },
    }, (res) => { res.on('data', () => {}); res.on('end', () => resolve()); });
    req.on('error', () => resolve());
    req.write(bodyStr);
    req.end();
  });
}

// A bare number is minor units directly, same convention as
// capture-text's own extraction (spec 0003 A7): "it was 35" is 0.35,
// not 35.00.
function extractAmountMinor(text) {
  const match = text.match(/(\d+)[.,](\d{1,2})\b|(?<!\d)(\d+)(?!\d*[.,]\d)/);
  if (!match) return null;
  if (match[1] !== undefined) return parseInt(match[1], 10) * 100 + parseInt(match[2].padEnd(2, '0'), 10);
  return parseInt(match[3], 10);
}

const DELETE_RE = /\b(?:delete|remove) (?:it|that|this)\b/i;
const AMOUNT_RE = /\bit was\s+\d+(?:[.,]\d{1,2})?\s*,?\s*(?:not|instead of|rather than)\s+\d+(?:[.,]\d{1,2})?/i;
const MERCHANT_RE = /\bit was (?:actually |really )?(?:at|from) ([A-Z][\w'&]*(?:\s+[A-Z&][\w'&]*)*)/;
const CATEGORY_RE = /\b(?:put (?:it|that) under|category (?:is|should be)|that'?s actually)\s+([a-z][\w ]*?)(?:\s+category)?\s*$/i;
const CONFIRM_RE = /^confirm:(\d+)$/i;
const FIXCAT_RE = /^fixcat:(\d+)$/i;
const CONFIRM_TYPED_RE = /^\s*(?:confirm|approve)\b/i;
const UNDO_RE = /^\s*undo\b/i;
const REMEMBER_RE = /^(?:remember|запомни)[:\s]+(.+)$/i;
const SAME_AGAIN_RE = /как обычно|same again|\bas usual\b/i;
const RECENT_LIST_RE = /\brecent (?:captures|expenses)\b|\blast few\b|\bmy (?:recent|last) expenses\b/i;
const LIST_UNCONFIRMED_RE = /\bunconfirmed\b|\bqueue\b|неподтвержд/i;
const CONFIRM_ALL_RE = /^\s*confirm all\b/i;

function formatAmount(minor, currency) {
  const major = (minor / 100).toFixed(2);
  return currency === 'EUR' ? `${major} €` : `${major} ${currency}`;
}

async function main() {
  const item = $input.first().json;
  const { member_id, chat_id, message_thread_id, text, language_hint } = item;
  const isRu = language_hint === 'ru';

  const readToken = mintToken('hh_agent', member_id);
  const readAuth = { Authorization: `Bearer ${readToken}` };

  const memberRes = await httpJson('GET', `${PG}/member?id=eq.${member_id}&select=role`, readAuth);
  const isAdmin = (memberRes.body && memberRes.body[0] && memberRes.body[0].role) === 'admin';
  const role = isAdmin ? 'hh_admin' : 'hh_member';
  const actingToken = mintToken(role, member_id);
  const auth = { Authorization: `Bearer ${actingToken}` };

  // R25a/ADR 0044: "remember" is the agent composing a standing fact
  // from what the member said, scoped to that member -- never a
  // financial fact, and read back as context by capture-text.json,
  // never here.
  const rememberMatch = text.match(REMEMBER_RE);
  if (rememberMatch) {
    await httpJson('POST', `${PG}/agent_memory`, Object.assign({ Prefer: 'return=minimal' }, readAuth), {
      member_id, content: rememberMatch[1].trim(),
    });
    return [{ json: { chat_id, message_thread_id, text: isRu ? 'Запомнил.' : 'Noted.' } }];
  }

  // R26/A35: "как обычно" repeats the member's own last capture --
  // same amount, category and account, dated today, unconfirmed. No
  // model call: there is nothing to interpret, only to copy.
  if (SAME_AGAIN_RE.test(text)) {
    const lastRes = await httpJson('GET', `${PG}/transaction?submitter=eq.${member_id}&order=id.desc&limit=1&select=id,merchant_id,category_source`, readAuth);
    const last = (lastRes.body || [])[0];
    if (!last) {
      return [{ json: { chat_id, message_thread_id, text: isRu ? 'Ещё нечего повторять.' : "There's nothing yet to repeat." } }];
    }
    const postingsRes = await httpJson('GET', `${PG}/posting?transaction_id=eq.${last.id}&select=account_id,amount,currency`, readAuth);
    const postings = postingsRes.body || [];
    const today = new Date().toISOString().slice(0, 10);
    const composeToken = mintToken('hh_agent', member_id);
    const composeAuth = { Authorization: `Bearer ${composeToken}` };
    const txnRes = await httpJson('POST', `${PG}/transaction`, Object.assign({ Prefer: 'return=representation' }, composeAuth), {
      date: today, submitter: member_id, source: 'manual', merchant_id: last.merchant_id, category_source: last.category_source,
    });
    const newTxnId = txnRes.body[0].id;
    await httpJson('POST', `${PG}/posting`, Object.assign({ Prefer: 'return=minimal' }, composeAuth),
      postings.map((p) => ({ transaction_id: newTxnId, account_id: p.account_id, amount: p.amount, currency: p.currency })));
    const expense = postings.find((p) => p.amount > 0);
    const amountText = expense ? formatAmount(expense.amount, expense.currency) : '';
    return [{ json: { chat_id, message_thread_id, text: isRu ? `Записал как обычно: ${amountText}.` : `Recorded, same as usual: ${amountText}.` } }];
  }

  // R27/A36: a short list of the member's own recent captures.
  if (RECENT_LIST_RE.test(text)) {
    const recentRes = await httpJson('GET', `${PG}/transaction?submitter=eq.${member_id}&order=id.desc&limit=5&select=id,date,confirmation_state`, readAuth);
    const recent = recentRes.body || [];
    if (!recent.length) {
      return [{ json: { chat_id, message_thread_id, text: isRu ? 'Пока ничего нет.' : 'Nothing recorded yet.' } }];
    }
    const lines = [];
    for (const t of recent) {
      const postingsRes = await httpJson('GET', `${PG}/posting?transaction_id=eq.${t.id}&amount=gt.0&select=amount,currency`, readAuth);
      const expense = (postingsRes.body || [])[0];
      const amountText = expense ? formatAmount(expense.amount, expense.currency) : '?';
      const stateLabel = t.confirmation_state === 'confirmed' ? (isRu ? 'подтверждено' : 'confirmed') : (isRu ? 'не подтверждено' : 'unconfirmed');
      lines.push(`#${t.id} ${t.date} ${amountText} (${stateLabel})`);
    }
    const header = isRu ? 'Последние траты (ответьте "подтвердить" или "undo" для последней):' : 'Recent captures (reply "confirm" or "undo" for the latest):';
    return [{ json: { chat_id, message_thread_id, text: `${header}\n${lines.join('\n')}` } }];
  }

  // R23: the "fix category" button has no single-tap outcome (it
  // needs a category), so it opens the same conversational path as
  // its typed equivalent -- CATEGORY_RE below -- by asking the
  // question a member would otherwise have answered up front.
  if (FIXCAT_RE.test(text)) {
    return [{ json: { chat_id, message_thread_id, text: isRu ? 'Какая категория? Например: "переведи это в транспорт".' : 'Which category? For example: "put it under transport".' } }];
  }

  // R20/A43: the admin-facing counterpart to A20 -- the whole
  // household's unconfirmed queue, listed and drainable in chat. Open
  // to any member reading it (R9 already makes the ledger visible to
  // everyone); "confirm all" is what actually drains it, gated by
  // hh_admin's own unconditional grant on transaction.
  if (LIST_UNCONFIRMED_RE.test(text)) {
    const unconfirmedRes = await httpJson('GET', `${PG}/transaction?confirmation_state=eq.unconfirmed&order=id.desc&select=id,date,submitter`, readAuth);
    const unconfirmed = unconfirmedRes.body || [];
    if (!unconfirmed.length) {
      return [{ json: { chat_id, message_thread_id, text: isRu ? 'Очередь пуста.' : 'The queue is empty.' } }];
    }
    const lines = [];
    for (const t of unconfirmed) {
      const postingsRes = await httpJson('GET', `${PG}/posting?transaction_id=eq.${t.id}&amount=gt.0&select=amount,currency`, readAuth);
      const expense = (postingsRes.body || [])[0];
      const amountText = expense ? formatAmount(expense.amount, expense.currency) : '?';
      lines.push(`#${t.id} ${t.date} ${amountText}`);
    }
    const header = isRu
      ? `Не подтверждено (${unconfirmed.length}). Напишите "confirm all", чтобы подтвердить все:`
      : `Unconfirmed (${unconfirmed.length}). Reply "confirm all" to confirm them all:`;
    return [{ json: { chat_id, message_thread_id, text: `${header}\n${lines.join('\n')}` } }];
  }

  if (CONFIRM_ALL_RE.test(text)) {
    if (!isAdmin) {
      return [{ json: { chat_id, message_thread_id, text: isRu ? 'Только администратор может подтвердить всё сразу.' : 'Only an admin can confirm the whole queue at once.' } }];
    }
    const confirmedAll = await httpJson('PATCH', `${PG}/transaction?confirmation_state=eq.unconfirmed`, Object.assign({ Prefer: 'return=minimal' }, auth), {
      confirmation_state: 'confirmed', confirmation_route: 'review', confirmed_by: member_id, confirmed_at: new Date().toISOString(),
    });
    if (confirmedAll.status >= 200 && confirmedAll.status < 300) {
      return [{ json: { chat_id, message_thread_id, text: isRu ? 'Всё подтверждено.' : 'All confirmed.' } }];
    }
    return [{ json: { chat_id, message_thread_id, text: isRu ? 'Не получилось подтвердить очередь.' : "Couldn't confirm the queue." } }];
  }

  // R23/A32: approve, whether tapped (callback_data "confirm:<id>") or
  // typed -- the outcome is identical either way, because both paths
  // end at the same PATCH, gated by the same grants and guard that
  // already prove R7b/R12 at the database.
  const confirmCallback = text.match(CONFIRM_RE);
  if (confirmCallback || CONFIRM_TYPED_RE.test(text)) {
    let targetId = confirmCallback ? Number(confirmCallback[1]) : null;
    if (!targetId) {
      const scope = isAdmin ? '' : `&submitter=eq.${member_id}`;
      const pendingRes = await httpJson('GET', `${PG}/transaction?confirmation_state=eq.unconfirmed&order=id.desc&limit=1&select=id${scope}`, readAuth);
      targetId = (pendingRes.body || [])[0] && pendingRes.body[0].id;
    }
    if (!targetId) {
      return [{ json: { chat_id, message_thread_id, text: isRu ? 'Нечего подтверждать.' : 'Nothing to confirm.' } }];
    }
    const patched = await httpJson('PATCH', `${PG}/transaction?id=eq.${targetId}`, Object.assign({ Prefer: 'return=minimal' }, auth), {
      confirmation_state: 'confirmed', confirmation_route: 'review', confirmed_by: member_id, confirmed_at: new Date().toISOString(),
    });
    if (patched.status >= 200 && patched.status < 300) {
      return [{ json: { chat_id, message_thread_id, text: isRu ? 'Подтверждено.' : 'Confirmed.' } }];
    }
    return [{ json: { chat_id, message_thread_id, text: isRu ? 'Не могу подтвердить эту запись.' : "I can't confirm that one." } }];
  }

  // R24/A33/ADR 0036: undo is scoped to the actor's OWN most recent
  // action, read straight from the audit log -- never the household's
  // last action, and never reaching further back. It is a new,
  // forward compensating change; nothing already written is touched.
  if (UNDO_RE.test(text)) {
    // A posting insert is a mechanical side effect of the transaction
    // insert right beside it, never an action of its own -- only a
    // transaction's own insert, or a posting UPDATE (a correction or
    // reclassification), counts as something to undo.
    const auditRes = await httpJson(
      'GET',
      `${PG}/audit_log?actor=eq.${member_id}&table_name=in.(transaction,posting)&order=id.desc&limit=10&select=id,table_name,row_id,operation,before_state`,
      readAuth
    );
    const lastAction = (auditRes.body || []).find(
      (a) => (a.table_name === 'transaction' && a.operation === 'insert') || (a.table_name === 'posting' && a.operation === 'update')
    );
    if (!lastAction) {
      return [{ json: { chat_id, message_thread_id, text: isRu ? 'Нечего отменять.' : "There's nothing of yours to undo." } }];
    }

    if (lastAction.operation === 'insert' && lastAction.table_name === 'transaction') {
      const originalTxnId = lastAction.row_id;
      const postingsRes = await httpJson('GET', `${PG}/posting?transaction_id=eq.${originalTxnId}&select=account_id,amount,currency`, readAuth);
      const postings = postingsRes.body || [];
      if (!postings.length) {
        return [{ json: { chat_id, message_thread_id, text: isRu ? 'Уже отменено.' : 'Already undone.' } }];
      }
      const composeToken = mintToken('hh_agent', member_id);
      const composeAuth = { Authorization: `Bearer ${composeToken}` };
      const today = new Date().toISOString().slice(0, 10);
      const reversalRes = await httpJson('POST', `${PG}/transaction`, Object.assign({ Prefer: 'return=representation' }, composeAuth), {
        date: today, submitter: member_id, source: 'manual', note: `undo of #${originalTxnId}`,
        confirmation_state: 'confirmed', confirmation_route: 'review', confirmed_by: member_id, confirmed_at: new Date().toISOString(),
      });
      const reversalId = reversalRes.body[0].id;
      await httpJson('POST', `${PG}/posting`, Object.assign({ Prefer: 'return=minimal' }, composeAuth),
        postings.map((p) => ({ transaction_id: reversalId, account_id: p.account_id, amount: -p.amount, currency: p.currency })));
      return [{ json: { chat_id, message_thread_id, text: isRu ? 'Отменено — записал компенсирующую проводку.' : 'Undone — a compensating entry was recorded.' } }];
    }

    if (lastAction.operation === 'update' && lastAction.table_name === 'posting' && lastAction.before_state) {
      // Only a reclassification (account_id) is ever this workflow's
      // own doing on posting for a plain member -- restore just that
      // field, never amount/currency, which a member could only have
      // changed under R7b's own gate and belongs to the amount-undo
      // path above instead.
      const restored = await httpJson(
        'PATCH', `${PG}/posting?id=eq.${lastAction.row_id}`, Object.assign({ Prefer: 'return=minimal' }, auth),
        { account_id: lastAction.before_state.account_id }
      );
      if (restored.status >= 200 && restored.status < 300) {
        return [{ json: { chat_id, message_thread_id, text: isRu ? 'Отменено.' : 'Undone.' } }];
      }
    }

    return [{ json: { chat_id, message_thread_id, text: isRu ? 'Это отменить пока нельзя.' : "That can't be undone here yet." } }];
  }

  // A financial-fact correction (amount, merchant, delete) targets
  // "the last one" as the most recent transaction overall for an
  // admin (R15's "any transaction"), and the member's own most recent
  // capture for anyone else (R7b) -- an admin's correction right
  // after a capture reply and a member's own correction of their own
  // spending are the two cases spec 0003's edge-case table names.
  // Reclassification (category/project) is never a financial fact
  // (R15a) and is unconditional for any member on any transaction, so
  // it always targets the most recent transaction overall regardless
  // of who submitted it.
  const scope = isAdmin ? '' : `&submitter=eq.${member_id}`;
  const [ownScopedRes, mostRecentRes] = await Promise.all([
    httpJson('GET', `${PG}/transaction?order=id.desc&limit=1&select=id,confirmation_state,submitter${scope}`, readAuth),
    httpJson('GET', `${PG}/transaction?order=id.desc&limit=1&select=id,confirmation_state,submitter`, readAuth),
  ]);
  const txn = (ownScopedRes.body || [])[0];
  const mostRecentTxn = (mostRecentRes.body || [])[0];
  if (!txn && !mostRecentTxn) {
    return [{ json: { chat_id, message_thread_id, text: isRu ? 'Не нашёл, что исправлять.' : "I don't have a recent transaction to correct." } }];
  }

  async function notifyAdmins(message) {
    const admins = await httpJson('GET', `${PG}/member?role=eq.admin&select=id`, readAuth);
    const botToken = $env.TELEGRAM_DELIVERY_MODE === 'polling' ? $env.TELEGRAM_LOCAL_BOT_TOKEN : $env.TELEGRAM_BOT_TOKEN;
    for (const admin of admins.body || []) {
      const channelRes = await httpJson('GET', `${PG}/member_channel?member_id=eq.${admin.id}&kind=eq.telegram&select=external_id`, readAuth);
      for (const channel of channelRes.body || []) {
        if (botToken) await telegramSend(botToken, channel.external_id, message);
      }
    }
  }

  async function requestInstead(field, requestedChange) {
    // tools/request_correction.json declares this "acts_as"/hh_member:
    // the member's own explicit request for a change they may not
    // make themselves (R16a) -- their own role, not the agent's.
    await httpJson('POST', `${PG}/correction_request`, Object.assign({ Prefer: 'return=minimal' }, auth), {
      transaction_id: txn.id, requested_by: member_id, requested_change: requestedChange, status: 'open',
    });
    const note = isRu
      ? 'Не могу изменить сам — запрос отправлен администраторам.'
      : "I can't change that myself -- the request has been sent to the admins.";
    await notifyAdmins(isRu
      ? `Запрос на исправление транзакции #${txn.id}: ${JSON.stringify(requestedChange)}`
      : `Correction requested for transaction #${txn.id}: ${JSON.stringify(requestedChange)}`);
    return note;
  }

  if (DELETE_RE.test(text) || AMOUNT_RE.test(text) || MERCHANT_RE.test(text)) {
    if (!txn) {
      return [{ json: { chat_id, message_thread_id, text: isRu ? 'Не нашёл, что исправлять.' : "I don't have a recent transaction to correct." } }];
    }
  }

  if (DELETE_RE.test(text)) {
    const del = await httpJson('DELETE', `${PG}/transaction?id=eq.${txn.id}`, auth);
    if (del.status >= 200 && del.status < 300) {
      return [{ json: { chat_id, message_thread_id, text: isRu ? 'Удалено.' : 'Deleted.' } }];
    }
    return [{ json: { chat_id, message_thread_id, text: isRu ? 'Только администратор может удалить запись.' : 'Only an admin can delete a record.' } }];
  }

  if (AMOUNT_RE.test(text)) {
    const newAmount = extractAmountMinor(text);
    // Both legs must be corrected in one commit -- posting_balance_check
    // is deferred to commit, so two separate PATCH requests would see
    // an unbalanced transaction at the first one's own commit.
    const corrected = await httpJson('POST', `${PG}/rpc/correct_posting_amounts`, auth, {
      p_transaction_id: txn.id, p_new_amount_minor: newAmount,
    });
    if (corrected.status >= 200 && corrected.status < 300) {
      return [{ json: { chat_id, message_thread_id, text: isRu ? 'Исправлено.' : 'Corrected.' } }];
    }
    const note = await requestInstead('amount', { amount_minor: newAmount });
    return [{ json: { chat_id, message_thread_id, text: note } }];
  }

  const merchantMatch = text.match(MERCHANT_RE);
  if (merchantMatch) {
    const merchantName = merchantMatch[1].trim();
    let merchantRes = await httpJson('GET', `${PG}/merchant?name=eq.${encodeURIComponent(merchantName)}&select=id`, readAuth);
    let merchantId = (merchantRes.body || [])[0] && merchantRes.body[0].id;
    if (!merchantId) {
      // A new merchant is the agent composing a registry entry from
      // what the member just said (ADR 0042), not a structural act.
      const agentToken = mintToken('hh_agent', member_id);
      const created = await httpJson('POST', `${PG}/merchant`, { Authorization: `Bearer ${agentToken}`, Prefer: 'return=representation' }, { name: merchantName });
      merchantId = created.body && created.body[0] && created.body[0].id;
    }
    const patched = await httpJson('PATCH', `${PG}/transaction?id=eq.${txn.id}`, Object.assign({ Prefer: 'return=minimal' }, auth), { merchant_id: merchantId });
    if (patched.status >= 200 && patched.status < 300) {
      return [{ json: { chat_id, message_thread_id, text: isRu ? 'Исправлено.' : 'Corrected.' } }];
    }
    const note = await requestInstead('merchant', { merchant_id: merchantId });
    return [{ json: { chat_id, message_thread_id, text: note } }];
  }

  const categoryMatch = text.match(CATEGORY_RE);
  if (categoryMatch) {
    if (!mostRecentTxn) {
      return [{ json: { chat_id, message_thread_id, text: isRu ? 'Не нашёл, что исправлять.' : "I don't have a recent transaction to correct." } }];
    }
    const categoryText = categoryMatch[1].trim();
    const transRes = await httpJson('GET', `${PG}/translation?display_name=ilike.*${encodeURIComponent(categoryText)}*&select=slug`, readAuth);
    let slug = (transRes.body || [])[0] && transRes.body[0].slug;
    if (!slug) slug = categoryText.toLowerCase().replace(/\s+/g, '-');
    const accountRes = await httpJson('GET', `${PG}/account?type=eq.expense&name=eq.${encodeURIComponent(slug)}&select=id`, readAuth);
    const accountId = (accountRes.body || [])[0] && accountRes.body[0].id;
    if (!accountId) {
      return [{ json: { chat_id, message_thread_id, text: isRu ? 'Не нашёл такую категорию.' : "I don't have that category." } }];
    }
    const postingsRes = await httpJson('GET', `${PG}/posting?transaction_id=eq.${mostRecentTxn.id}&amount=gt.0&select=id`, readAuth);
    const categoryPosting = (postingsRes.body || [])[0];
    if (!categoryPosting) {
      return [{ json: { chat_id, message_thread_id, text: isRu ? 'Не нашёл строку категории.' : "I couldn't find the category posting." } }];
    }
    // R15a: classification is never a financial fact, so this always
    // applies -- unconditional for any member, proven at the database
    // by db/tests/013_ledger_row_level_security.sql.
    await httpJson('PATCH', `${PG}/posting?id=eq.${categoryPosting.id}`, Object.assign({ Prefer: 'return=minimal' }, auth), { account_id: accountId });
